interface.definition:
a!localVariables(
  local!teamdetails: if(
    a!isNotNullOrEmpty(ri!teamid),
    #"_a-0000eef8-4604-8000-9e54-011c48011c48_1132811"(TeamId: ri!teamid),
    null()
  ),
  #"SYSTEM_SYSRULES_formLayout_v2"(
    contents: {
      #"_a-0000eef8-4604-8000-9e54-011c48011c48_1132792"(team: local!teamdetails)
    },
    buttons: #"SYSTEM_SYSRULES_ButtonLayout"(
      primaryButtons: {
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          label: "Submit",
          submit: true,
          saveInto: {
            if(
              ri!isUpdate,
              {
                a!save(
                  target: local!teamdetails[#"urn:appian:record-field:v1:bb51e73c-01e7-4e73-8a7b-4187491dde54/05a3d9d2-435f-40db-b1ba-b738884ea0ac"],
                  value: loggedInUser()
                ),
                a!save(
                  target: local!teamdetails[#"urn:appian:record-field:v1:bb51e73c-01e7-4e73-8a7b-4187491dde54/da7add7a-4e14-48f7-842f-e3df624f4c00"],
                  value: now()
                )
              },
              {
                a!save(
                  target: ri!team[#"urn:appian:record-field:v1:bb51e73c-01e7-4e73-8a7b-4187491dde54/5b3116d5-79dc-4937-ae25-673207c3df2b"],
                  value: loggedInUser()
                ),
                a!save(
                  target: ri!team[#"urn:appian:record-field:v1:bb51e73c-01e7-4e73-8a7b-4187491dde54/b2e82a3c-b634-46f9-9efc-0e0e134f4000"],
                  value: now()
                ),
                a!save(
                  target: ri!team[#"urn:appian:record-field:v1:bb51e73c-01e7-4e73-8a7b-4187491dde54/7db87751-26a5-4ea2-9c9e-53e78cf84bc1"],
                  value: true()
                ),

              }
            ),
            a!save(target: ri!team, value: local!teamdetails),
            a!save(
              target: ri!button,
              value: #"_a-0000eeda-0177-8000-9e52-011c48011c48_1085463"
            )
          },
          loadingIndicator: true,
          style: "SOLID"
        )
      },
      secondaryButtons: {
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          label: "Cancel",
          value: true,
          saveInto: {
            a!save(
              target: ri!button,
              value: #"_a-0000eeda-0177-8000-9e52-011c48011c48_1085469"
            )
          },
          validate: false,
          submit: true,
          style: "OUTLINE"
        )
      }
    ),
    titleBar: #"SYSTEM_SYSRULES_headerTemplateFull"(
      title: if(
        a!isNotNullOrEmpty(ri!isUpdate),
        "Update Team",
        "Create Team"
      ),
      secondaryText: if(
        a!isNotNullOrEmpty(ri!isUpdate),
        "Update Team Details",
        "Enter team details"
      ),
      backgroundColor: "ACCENT"
    ),
    showTitleBarDivider: false
  )
)
